"""Tests for the API client configuration."""
import os
import pytest

from src.api_client import API_KEY


class TestAPIKey:
    @pytest.mark.parametrize('config_value', [None, 'test_key', 'sk-prod-ABCDEF12345'])
    def test_api_key_is_provided(self, config_value):
        # Ensure API_KEY is set before testing
        if config_value is None:
            os.environ.pop('API_KEY', None)
        else:
            os.environ['API_KEY'] = config_value

        assert API_KEY == config_value

    @pytest.mark.parametrize('config_value', [None, 'test_key', 'sk-prod-ABCDEF12345'])
    def test_api_key_uses_env_when_provided(self, config_value):
        if config_value is None:
            os.environ.pop('API_KEY', None)
        else:
            os.environ['API_KEY'] = config_value

        assert API_KEY == config_value


if __name__ == '__main__':
    pytest.main([__file__, '-v'])

